const body = $input.item.json.body || $input.item.json;

const invoiceId    = body.invoice_id    || null;
const orgId        = body.organization_id || null;
const notaasId     = body.notaas_id     || null;
const numero       = body.numero        || null;
const clientId     = body.client_id     || null;
const paymentId    = body.payment_id    || null;
const contractId   = body.contract_id   || null;
const competencia  = body.competencia   || null;
const valorServico = body.valor_servico || 0;
const aliquotaIss  = body.aliquota_iss  || null;
const codigoServico    = body.codigo_servico    || null;
const descricaoServico = body.descricao_servico || null;
const tomadorNome      = body.tomador_nome      || null;
const tomadorDoc       = body.tomador_cnpj_cpf  || null;
const emitidaEm        = body.emitida_em        || null;
// Contador de tentativas de polling (incrementado a cada loop)
const attempt = parseInt(body._attempt || '0', 10);

if (!invoiceId)  throw new Error('invoice_id é obrigatório');
if (!orgId)      throw new Error('organization_id é obrigatório');
if (!notaasId)   throw new Error('notaas_id é obrigatório para buscar o PDF');

return [{ json: {
  invoice_id:        invoiceId,
  organization_id:   orgId,
  notaas_id:         notaasId,
  numero,
  client_id:         clientId,
  payment_id:        paymentId,
  contract_id:       contractId,
  competencia,
  valor_servico:     valorServico,
  aliquota_iss:      aliquotaIss,
  codigo_servico:    codigoServico,
  descricao_servico: descricaoServico,
  tomador_nome:      tomadorNome,
  tomador_cnpj_cpf:  tomadorDoc,
  emitida_em:        emitidaEm,
  _attempt:          attempt
}}];

const items = $input.all();
const parsed = $('Parsear Payload').item.json;

let invoice = null;
let config  = {};
let client  = null;

for (const item of items) {
  const j = item?.json;
  if (!j) continue;
  if (j.integration_type === 'notaas' || (j.config && j.config.api_key !== undefined)) {
    config = j.config ?? {};
  } else if (j.valor_servico !== undefined || j.type === 'nfse') {
    invoice = j;
  } else if (j.folder_id !== undefined || j.address_city !== undefined) {
    client = j;
  }
}

if (!invoice?.id)    throw new Error('Invoice não encontrado: ' + parsed.invoice_id);
if (!config.api_key) throw new Error('API Key da Notaas não configurada');
if (!client?.id)     throw new Error('Cliente não encontrado: ' + parsed.client_id);

const notaasId = invoice.notaas_id || parsed.notaas_id;
if (!notaasId) throw new Error('notaas_id não disponível — nota ainda não foi enviada à Notaas');

const baseUrl = config.sandbox_mode === true
  ? 'https://sandbox.notaas.com.br'
  : 'https://platform.notaas.com.br';

const folderId   = client.folder_id || null;
const clientName = (client.company || client.name || 'cliente').replace(/[^a-zA-Z0-9 ]/g, '').trim().slice(0, 40);

const numero = invoice.numero || parsed.numero || notaasId;
const competencia = (invoice.competencia || parsed.competencia || '').replace('-', '_');
const fileName = 'NFS-e_' + numero + (competencia ? '_' + competencia : '') + '_' + clientName + '.pdf';

return [{ json: {
  invoice_id:      invoice.id,
  organization_id: invoice.organization_id,
  notaas_id:       notaasId,
  numero,
  client_id:       invoice.client_id,
  folder_id:       folderId,
  file_name:       fileName,
  api_key:         config.api_key,
  base_url:        baseUrl,
  _attempt:        parsed._attempt || 0
}}];

// Normaliza a resposta da Notaas e determina o fluxo
const httpResp = $input.item.json;
const prep     = $('Preparar Consulta').item.json;

const statusCode = httpResp.statusCode || 0;
const body = httpResp.body || httpResp;

// Status retornado pela Notaas: issued | processing | queued | error | cancelled
const notaasStatus = (typeof body === 'object')
  ? (body.status || body.situacao || body.state || '').toLowerCase()
  : '';

const pdfUrl = (typeof body === 'object')
  ? (body.pdf_url || body.pdfUrl || body.link_pdf || null)
  : null;

let flow;
if (statusCode >= 500) {
  flow = 'error';
} else if (statusCode === 404) {
  flow = 'error';
} else if (!statusCode || statusCode >= 400) {
  flow = 'error';
} else if (notaasStatus === 'issued' || notaasStatus === 'autorizada' || notaasStatus === 'emitida') {
  flow = 'issued';
} else if (notaasStatus === 'processing' || notaasStatus === 'processando' || notaasStatus === 'queued' || notaasStatus === 'aguardando') {
  flow = 'processing';
} else {
  // Status desconhecido ou erro da Notaas
  flow = 'error';
}

const errorMsg = flow === 'error'
  ? ((typeof body === 'object' ? (body.message || body.error || body.msg || body.detail) : String(body)) || ('HTTP ' + statusCode))
  : null;

return [{ json: {
  ...prep,
  flow,
  notaas_status: notaasStatus,
  pdf_url:       pdfUrl,
  error_msg:     errorMsg,
  http_status:   statusCode,
  _attempt:      (prep._attempt || 0) + 1
}}];

// Reusa os dados já preparados para re-consultar a Notaas
const d = $input.item.json;
return [{ json: {
  invoice_id:      d.invoice_id,
  organization_id: d.organization_id,
  notaas_id:       d.notaas_id,
  numero:          d.numero,
  client_id:       d.client_id,
  folder_id:       d.folder_id,
  file_name:       d.file_name,
  api_key:         d.api_key,
  base_url:        d.base_url,
  _attempt:        d._attempt || 0
}}];

// Baixa o PDF da Notaas e faz upload no Google Drive
const d = $input.item.json;

if (!d.pdf_url) throw new Error('pdf_url não disponível mesmo com status issued');
if (!d.folder_id) throw new Error('Cliente não possui pasta no Google Drive (folder_id ausente)');

// Helper: fetch com retry para 502/503/504
async function fetchWithRetry(url, options, maxRetries) {
  const delays = [3000, 8000, 15000];
  let lastErr;
  for (let i = 0; i <= (maxRetries || 2); i++) {
    try {
      const res = await fetch(url, options);
      if ((res.status === 502 || res.status === 503 || res.status === 504) && i < (maxRetries || 2)) {
        await new Promise(function(r) { setTimeout(r, delays[i] || 15000); });
        continue;
      }
      return res;
    } catch (e) {
      lastErr = e;
      if (i < (maxRetries || 2)) await new Promise(function(r) { setTimeout(r, delays[i] || 15000); });
    }
  }
  throw lastErr || new Error('Falha após ' + (maxRetries || 2) + ' tentativas');
}

// 1. Baixa o PDF
const pdfRes = await fetchWithRetry(
  d.pdf_url,
  { headers: { 'x-api-key': d.api_key }, signal: AbortSignal.timeout(60000) },
  3
);
if (!pdfRes.ok) {
  const hint = (pdfRes.status === 502 || pdfRes.status === 503)
    ? ' Notaas temporariamente indisponível.'
    : '';
  throw new Error('Erro ao baixar PDF: HTTP ' + pdfRes.status + '.' + hint);
}
const pdfBuffer = await pdfRes.arrayBuffer();
const pdfBase64 = Buffer.from(pdfBuffer).toString('base64');

// 2. Upload multipart para o Google Drive
// Nota: usa GOOGLE_ACCESS_TOKEN da variável de ambiente
const googleToken = $env.GOOGLE_ACCESS_TOKEN;
if (!googleToken) throw new Error('Variável GOOGLE_ACCESS_TOKEN não configurada');

const boundary = 'nfse_pdf_boundary_271828';
const metadata = JSON.stringify({
  name: d.file_name,
  parents: [d.folder_id],
  mimeType: 'application/pdf',
  description: 'NFS-e ' + d.numero + ' — ' + d.file_name
});
const multipartBody =
  '--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' +
  metadata +
  '\r\n--' + boundary + '\r\nContent-Type: application/pdf\r\nContent-Transfer-Encoding: base64\r\n\r\n' +
  pdfBase64 +
  '\r\n--' + boundary + '--';

const driveRes = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + googleToken,
    'Content-Type': 'multipart/related; boundary=' + boundary
  },
  body: multipartBody,
  signal: AbortSignal.timeout(120000)
});

if (!driveRes.ok) {
  const driveErr = await driveRes.json().catch(function() { return {}; });
  throw new Error('Erro no upload Google Drive: ' + (driveErr.error?.message || driveRes.status));
}

const driveData = await driveRes.json();
const driveFileId  = driveData.id;
const driveFileUrl = 'https://drive.google.com/file/d/' + driveFileId + '/view';

return [{ json: {
  invoice_id:      d.invoice_id,
  organization_id: d.organization_id,
  notaas_id:       d.notaas_id,
  drive_file_id:   driveFileId,
  drive_file_url:  driveFileUrl,
  notaas_pdf_url:  d.pdf_url,
  file_name:       d.file_name
}}];

// Prepara os dados do erro — salva em metadata.pdf_error (não em erro_mensagem)
const d = $input.item.json;
const errMsg = d.error_msg || 'Erro desconhecido ao consultar nota na Notaas';
const detail = 'status=' + (d.notaas_status || '?') + ' http=' + (d.http_status || '?') + ' — ' + errMsg;

// Busca o metadata atual para fazer merge sem sobrescrever outros campos
const sbUrl = $env.SUPABASE_URL;
const sbKey  = $env.SUPABASE_SERVICE_KEY;

let currentMeta = {};
try {
  const res = await fetch(sbUrl + '/rest/v1/invoices?id=eq.' + d.invoice_id + '&select=metadata', {
    headers: { 'apikey': sbKey, 'Authorization': 'Bearer ' + sbKey }
  });
  if (res.ok) {
    const arr = await res.json();
    currentMeta = (Array.isArray(arr) ? arr[0]?.metadata : arr?.metadata) || {};
  }
} catch (e) { /* best-effort */ }

const newMeta = Object.assign({}, currentMeta, {
  pdf_error:    detail,
  pdf_error_at: new Date().toISOString()
});

await fetch(sbUrl + '/rest/v1/invoices?id=eq.' + d.invoice_id, {
  method: 'PATCH',
  headers: {
    'apikey': sbKey,
    'Authorization': 'Bearer ' + sbKey,
    'Content-Type': 'application/json',
    'Prefer': 'return=minimal'
  },
  body: JSON.stringify({ metadata: newMeta })
});

return [{ json: {
  invoice_id:    d.invoice_id,
  organization_id: d.organization_id,
  error_detail:  detail,
  notaas_status: d.notaas_status || null,
  http_status:   d.http_status   || null
}}];
